head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "Url(필수) 파라미터로 팝업에 표시할 페이지의 URL 경로를 설정할 수 있어야 합니다.",
        "options(필수) 파라미터로 팝업 옵션을 JSON 객체로 설정할 수 있어야 합니다.",
        "options.id(선택) 파라미터로 팝업의 ID 를 설정할 수 있어야 합니다.",
        "options.type(선택) 파라미터를 'wframePopup' 으로 설정하면 wFrame 방식의 내부 팝업이 생성되어야 합니다.",
        "options.type(선택) 파라미터를 'iframePopup' 으로 설정하면 iFrame 방식의 내부 팝업이 생성되어야 합니다.",
        "options.type(선택) 파라미터를 'browserPopup' 으로 설정하면 window.open() 독립창으로 팝업이 생성되어야 합니다.",
        "options.type(선택) 파라미터 생략 시 기본값 'browserPopup' 으로 동작해야 합니다.",
        "options.modal(선택) 파라미터를 true 로 설정하면 부모 창을 컨트롤 할 수 없어야 합니다.",
        "options.modal(선택) 파라미터를 false 로 설정하면 부모 창을 컨트롤 할 수 있어야 합니다.",
        "options.modal(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "options.width(선택) 파라미터로 팝업의 너비를 설정할 수 있어야 합니다.",
        "options.height(선택) 파라미터로 팝업의 높이를 설정할 수 있어야 합니다.",
        "options.left(선택) 파라미터로 팝업의 좌측 위치를 설정할 수 있어야 합니다.",
        "options.top(선택) 파라미터로 팝업의 상단 위치를 설정할 수 있어야 합니다.",
        "options.popupName(선택) 파라미터로 팝업의 타이틀바 이름을 설정할 수 있어야 합니다.",
        "options.dataObject(선택) 파라미터로 팝업에 전달할 데이터를 JSON 객체로 설정할 수 있어야 합니다.",
        "options.dataObject.type(선택) 파라미터로 전달할 데이터의 종류를 'json', 'string', 'xml', 'array' 중 하나로 설정할 수 있어야 합니다.",
        "options.dataObject.name(선택) 파라미터로 팝업에서 $p.getParameter() 로 접근할 이름을 설정할 수 있어야 합니다.",
        "options.useModalStack(선택) 파라미터를 true 로 설정하면 마지막 팝업만 활성화되어야 합니다.",
        "options.useModalDisable(선택) 파라미터를 true 로 설정하면 부모 창의 컴포넌트가 비활성화되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_onclick = function () {
    let type = par_type.getValue();
    let modal = par_modal.getValue();
    let useDataObject = par_dataObject.getValue();

    let options = {
        id: "popup_test_1",
        type: type,
        width: "500px",
        height: "350px",
        top: "150px",
        left: "200px",
        popupName: "openPopup 테스트"
    };

    if (modal !== '') {
        options.modal = (modal === 'true');
    }

    if (useDataObject === 'true') {
        options.dataObject = {
            type: "json",
            name: "paramData",
            data: {"Name": "홍길동", "Age": 30, "Dept": "개발팀"}
        };
    }

    wf_body_bottom.getObj("scwin").setReturnValue("options : " + JSON.stringify(options, null, 2));

    WebSquare.util.openPopup("/sample/common_link/util_openPopup_1.xml", options);

    // 팝업 생성 검증 (wframePopup/iframePopup인 경우)
    if (type !== 'browserPopup') {
        setTimeout(function () {
            let result = [];
            let popupEl = document.querySelector("div[id='popup_test_1']");
            result.push("팝업 존재 : " + (popupEl ? "PASS" : "FAIL"));

            if (popupEl) {
                result.push("style.width: " + popupEl.style.width);
                result.push("style.height: " + popupEl.style.height);
            }

            if (modal === 'true') {
                let modalOverlay = document.querySelector(".w2modalopenedbody");
                result.push("모달 배경 존재 : " + (modalOverlay ? "PASS" : "FAIL"));
            }

            wf_body_bottom.getObj("scwin").setReturnValue(result.join("\n"));
        }, 1000);
    }
}
